 "content": "def transform(grid):
    """Complete the cyclic row pattern, shifting the prefix left of the diagonal."""
    h, w = len(grid), len(grid[0])
    first = grid[0]

    # Infer the shortest cycle consistent with all visible cells in row zero.
    period = None
    for p in range(1, w + 1):
        pattern = [None] * p
        valid = True
        for c, value in enumerate(first):
            if value == 0:
                continue
            k = c % p
            if pattern[k] is None:
                pattern[k] = value
            elif pattern[k] != value:
                valid = False
                break
        if valid and all(value is not None for value in pattern):
            period = p
            break

    if period is None:
        raise ValueError("Could not infer a complete cycle from the first row")

    pattern = [None] * period
    for c, value in enumerate(first):
        if value:
            pattern[c % period] = value

    return [[pattern[(c + (1 if c < r else 0)) % period]
             for c in range(w)] for r in range(h)]
